cd "C:/Users/HUAWEI/AppData/Local/Temp/claude/D--Projects-AgentCAD/d6ee3478-e055-493d-8b14-3ab652e01571/scratchpad/cc_code/T1_flange" && PY="C:/Users/HUAWEI/AppData/Local/Temp/claude/D--Projects-AgentCAD/2ae4a084-56e6-4620-bc3c-41e08c1aeab6/scratchpad/armB/venv/Scripts/python.exe" && "$PY" make_flange.py && cat > check.py <<'EOF'
import ezdxf, math
doc = ezdxf.readfile("flange.dxf")
msp = doc.modelspace()
print("audit errors:", len(doc.audit().errors))
for e in msp:
    t = e.dxftype()
    if t == "CIRCLE":
        c = e.dxf.center
        print(f"CIRCLE layer={e.dxf.layer} lt={doc.layers.get(e.dxf.layer).dxf.linetype} c=({c.x:.3f},{c.y:.3f}) D={2*e.dxf.radius:.3f}")
    elif t == "LINE":
        print(f"LINE layer={e.dxf.layer} {tuple(round(v,2) for v in e.dxf.start)[:2]} -> {tuple(round(v,2) for v in e.dxf.end)[:2]}")
    elif t == "DIMENSION":
        print(f"DIM type={e.dimtype} meas={e.get_measurement():.3f} text={e.dxf.text!r} p10={tuple(round(v,2) for v in e.dxf.defpoint)[:2]} p15={tuple(round(v,2) for v in e.dxf.defpoint4)[:2]} block={e.dxf.geometry}")
        blk = doc.blocks[e.dxf.geometry]
        for b in blk:
            if b.dxftype()=="MTEXT": print("   mtext:", b.text, tuple(round(v,1) for v in b.dxf.insert)[:2])
EOF
"$PY" check.py

